"""This file contains Classes with the functionality for the Clinical menu bar and Receive External Prescriptions (REP) page objects"""

import logging
from interops.libraries.desktop.base_ui_page_object import BaseUIPageObject
from interops.libraries.integrity.pages.common_menu_bars import get_object_text
import interops.libraries.desktop.decorators as deco
from interops.libraries.squish_actions.constants import INTEGRITY_APP_NAME
from interops.libraries.verify.verify import VerifyThat
import interops.libraries.integrity.integrity_objects as integrity_objects
from ..interactions.objects.integrity_clinical_objects import IntegrityClinicalObjects
from ..interactions import ClinicalAdministerSystem
from typing import Optional as opt
from typing import Dict
import squishtest3 as sq


logger = logging.getLogger(__name__)

class ClinicalMenuBar(BaseUIPageObject):

    application_name = "RTDShell"

    def ready(self):
        try:
            sq.waitForObjectExists(IntegrityClinicalObjects.menuBar_Clinical_REP_Button)
            return True
        except Exception:
            return False

    # ToT=Yes
    def rep_prescription(self):
        try:
            # super(ClinicalMenuBar, self).mouseClick(IntegrityClinicalObjects.menuBar_Clinical_REP_Button)
            # REP mode sometimes doesn't get clciked. Try holding down mouse click for a second.
            sq.snooze(1)
            sq.mousePress(IntegrityClinicalObjects.menuBar_Clinical_REP_Button)
            sq.snooze(1)
            sq.mouseRelease(IntegrityClinicalObjects.menuBar_Clinical_REP_Button)
        except Exception as e:
            logger.info("REP already started is " + str(sq.object.exists({'text': ' Receive External Prescription'})))

    def administer_system_customize_system_settings(self):
        try:
            ClinicalAdministerSystem.click_administer_system_button()
            ClinicalAdministerSystem.click_customize_system_settings_button()
        except Exception as e:
            logger.info("Unable to open Customize System Settings page")

    # ToT=Yes
    def log_off(self):

        super(ClinicalMenuBar, self).mouseClick(integrity_objects.clinical_Menubutton_LogOff)
        sq.snooze(2)
        try:
            super(ClinicalMenuBar, self).mouseClick(integrity_objects.confirm_LogOff)
        except Exception as e:
            logger.debug("Logoff not confirmed,trying once more " + str(e))
            super(ClinicalMenuBar, self).mouseClick(integrity_objects.clinical_Menubutton_LogOff)
            sq.snooze(2)
            super(ClinicalMenuBar, self).mouseClick(integrity_objects.confirm_LogOff)

        try:
            sq.mouseClick(sq.waitForObject(integrity_objects.no_Button))
        except Exception:
            pass

        try:
            sq.waitForObjectExists(integrity_objects.login_About_Button)
            return True
        except Exception as e:
            logger.debug("Cannot see login page " + str(e))
            return False


class ReceiveExternalPrescription(BaseUIPageObject):

    application_name = "RTDShell"

    # Note: AUT context should switch to RTDShell at this point as this is handled by BaseUIPageObject,
    # however the context sometimes does not change when coming from Mosaiq, so use the decorator to
    # set the context again
    @deco.set_separate_app_context(application_name=INTEGRITY_APP_NAME)
    def ready(self):
        try:
            try:
                sq.waitForObjectExists(IntegrityClinicalObjects.rEP_Exit_Button, 3000)
            except Exception:                # try 4TCS version
                sq.waitForObjectExists({"container": integrity_objects.rEP_FRMDeliveryMonitorCmd, "width": 305}, 8000)
                sq.snooze(5)
            return True
        except Exception:
            return False

    def get_info_bar_text(self):
        return get_object_text({'id': '1011'})

    # ToT=Yes
    @deco.app_ctx_function()
    def exit(self):

        #         sq.waitForObjectExists(IntegrityClinicalObjects.rEP_Exit_Button)
        #         super( ReceiveExternalPrescription, self).mouseClick(IntegrityClinicalObjects.rEP_Exit_Button)
        #         Change to make exiting REP more robust
        try:
            try:
                # REP Exit button for 3TCS
                sq.doubleClick(sq.waitForObjectExists(IntegrityClinicalObjects.rEP_Exit_Button, 2000))
            except Exception:                # REP Exit button for 4TCS appears to be a different object type from 3TCS
                logger.info("3TCS Exit REP button not found. Trying 4TCS version...")
                sq.doubleClick(sq.waitForObjectExists(
                    {"container": integrity_objects.rEP_FRMDeliveryMonitorCmd, "width": 305}))
        except Exception:
            return False


# Utility function to restart REP
def restart_rep(icom_obj, linac_id, ip_addr, exit_first=True):
    rep = ReceiveExternalPrescription()
    menu = ClinicalMenuBar()
    if exit_first:
        try:
            rep.exit()
            icom_obj.disconnect()
        except Exception:
            logger.info("REP not found nothing to exit")

    sq.snooze(3)
    menu.rep_prescription()
    sq.snooze(10)
    # Connect iCOM to REP
    VerifyThat(icom_obj.set_server_connections(linac_id, ip_addr)).equals(
        True).andReportCritical("set_server_connections")
    sq.snooze(5)
    VerifyThat(icom_obj.check_fx_connection()).equals(True).andReportCritical("check_fx_connection")
    VerifyThat(icom_obj.check_vx_connection()).equals(True).andReportCritical("check_vx_connection")
    VerifyThat(rep.get_info_bar_text().strip()).equals(
        "External client system connected.").andReport("External client system connected message")
    return rep


class CustomizeSystemSettings():

    def ready(self) -> bool:
        '''
        Waits for Customize Systems Settings pane to be ready.

        Returns:
            bool - True if Customize Systems Settings pane is ready, False otherwise
        '''
        try:
            return ClinicalAdministerSystem.wait_for_main_customize_system_settings_pane(wait_timeout=5000)
        except Exception:
            logger.info("Customize System Settings Main Pane failed to open")
            return False

    def select_tolerances_table_tab(self) -> None:
        '''
        Selects the Tolerance Tables Tab in the Customize System Settings pane.
        '''
        ClinicalAdministerSystem.click_tolerance_tables_tab()

    def tolerance_tables_pane_ready(self, wait_timeout: int=2000) -> bool:
        '''
        Waits for Tolerance Table pane to be ready.

        Args:
            wait_timeout (int): Duration of time (in milliseconds) to wait for Tolerance
                                Table pane to be ready
        Returns:
            bool - True if Tolerance Table pane is ready, False otherwise
        '''
        try:
            return ClinicalAdministerSystem.wait_for_tolerance_tables_pane(wait_timeout)
        except Exception as e:
            logger.info("Failed to locate Tolerance Table pane.")
            return False


    def select_tolerance_table_name_from_list(self, tolerance_table_name: str) -> None:
        '''
        Selects the tolerance table name from the list on the Tolerance Table pane.

        Args:
            tolerance_table_name (str): Name of the tolerance table to select.
                                        Can be "XRAY", "ELECTRON", "SERVICE 1" or "ICOM"
        '''
        ClinicalAdministerSystem.select_tolerance_from_list(tolerance_table_name)

    def get_tolerance_geometric_parameter_value(self, geometric_parameter_to_read: str) -> opt[str]:
        '''
        Gets the specified parameter value from the edit field in the Tolerance Table pane
        and returns it if found.

        Args:
            geometric_parameter_to_read (str): Name of geometric parameter to read value from.
                                        Geometric parameter can be one of the following:
                                        "Diaphragm Y2", "Diaphragm Y1", "Diaphragm X2",
                                        "Diaphragm X1", "Fieldsize X", "Fieldsize Y",
                                        "Field Offset X", "Field Offset Y", "Collimator Angle",
                                        "Gantry Angle", "Table Vertical", "Table Lateral",
                                        "Table Longitudinal", "Column Rotation", "Isocentric Rotation"

        Returns:
            str or None: Geometric parameter value or None if not found
        '''
        if geometric_parameter_to_read.casefold() == "Diaphragm Y2".casefold():
            return ClinicalAdministerSystem.get_tolerance_geometric_parameter_diaphragm_Y2_value()
        elif geometric_parameter_to_read.casefold() == "Diaphragm Y1".casefold():
            return ClinicalAdministerSystem.get_tolerance_geometric_parameter_diaphragm_Y1_value()
        elif geometric_parameter_to_read.casefold() == "Diaphragm X2".casefold():
            return ClinicalAdministerSystem.get_tolerance_geometric_parameter_diaphragm_X2_value()
        elif geometric_parameter_to_read.casefold() == "Diaphragm X1".casefold():
            return ClinicalAdministerSystem.get_tolerance_geometric_parameter_diaphragm_X1_value()
        elif geometric_parameter_to_read.casefold() == "Fieldsize X".casefold():
            return ClinicalAdministerSystem.get_tolerance_geometric_parameter_fieldsize_X_value()
        elif geometric_parameter_to_read.casefold() == "Fieldsize Y".casefold():
            return ClinicalAdministerSystem.get_tolerance_geometric_parameter_fieldsize_Y_value()
        elif geometric_parameter_to_read.casefold() == "Field Offset X".casefold():
            return ClinicalAdministerSystem.get_tolerance_geometric_parameter_field_offset_X_value()
        elif geometric_parameter_to_read.casefold() == "Field Offset Y".casefold():
            return ClinicalAdministerSystem.get_tolerance_geometric_parameter_field_offset_Y_value()
        elif geometric_parameter_to_read.casefold() == "Collimator Angle".casefold():
            return ClinicalAdministerSystem.get_tolerance_geometric_parameter_collimator_angle_value()
        elif geometric_parameter_to_read.casefold() == "Gantry Angle".casefold():
            return ClinicalAdministerSystem.get_tolerance_geometric_parameter_gantry_angle_value()
        elif geometric_parameter_to_read.casefold() == "Table Vertical".casefold():
            return ClinicalAdministerSystem.get_tolerance_geometric_parameter_table_vertical_value()
        elif geometric_parameter_to_read.casefold() == "Table Lateral".casefold():
            return ClinicalAdministerSystem.get_tolerance_geometric_parameter_table_lat_value()
        elif geometric_parameter_to_read.casefold() == "Table Longitudinal".casefold():
            return ClinicalAdministerSystem.get_tolerance_geometric_parameter_table_long_value()
        elif geometric_parameter_to_read.casefold() == "Column Rotation".casefold():
            return ClinicalAdministerSystem.get_tolerance_geometric_parameter_column_rotation_value()
        elif geometric_parameter_to_read.casefold() == "Isocentric Rotation".casefold():
            return ClinicalAdministerSystem.get_tolerance_geometric_parameter_isocentric_rotation_value()
        else:
            return None

    def set_tolerance_geometric_parameter_values(self, geometric_param_name_value_pairs: Dict[str, str]) -> None:
        '''
        Modifies one or more geometric parameter fields in the Tolerance Tables pane as specified
        in the dicitonary arg of geometric parameter field name key: set value pairs.

        Args:
            geometric_param_name_value_pairs (dict of str: str): Dictionary of geometric parameter
            field name to set string as the key, and string value to set as the value.

            Geometric Parameter Keys can be one of the following strings:
                "Diaphragm Y2", "Diaphragm Y1", "Collimator Angle", "Gantry Angle",
                "Table Vertical", "Table Lateral", "Table Longitudinal", "Column Rotation"
        '''
        for key, value in geometric_param_name_value_pairs.items():
            if key.casefold() == "Diaphragm Y2".casefold():
                ClinicalAdministerSystem.set_tolerance_geometric_parameter_diagphragm_Y2_value(value)
            elif key.casefold() == "Diaphragm Y1".casefold():
                ClinicalAdministerSystem.set_tolerance_geometric_parameter_diagphragm_Y1_value(value)
            elif key.casefold() == "Collimator Angle".casefold():
                ClinicalAdministerSystem.set_tolerance_geometric_parameter_collimator_angle_value(value)
            elif key.casefold() == "Gantry Angle".casefold():
                ClinicalAdministerSystem.set_tolerance_geometric_parameter_gantry_angle_value(value)
            elif key.casefold() == "Table Vertical".casefold():
                ClinicalAdministerSystem.set_tolerance_geometric_parameter_table_vertical_value(value)
            elif key.casefold() == "Table Lateral".casefold():
                ClinicalAdministerSystem.set_tolerance_geometric_parameter_table_lateral_value(value)
            elif key.casefold() == "Table Longitudinal".casefold():
                ClinicalAdministerSystem.set_tolerance_geometric_parameter_table_longitudinal_value(value)
            elif key.casefold() == "Column Rotation".casefold():
                ClinicalAdministerSystem.set_tolerance_geometric_parameter_column_rotation_value(value)
            else:
                logger.info(f"Invalid geometric parameter: {key}, unable to set")

    def save_and_confirm_geometric_parameter_value_change(self) -> bool:
        '''
        Selects the Save button on the Customize System Settings pane if
        it is enabled and confirms the change in the confirmation dialog.

        Returns:
            bool - True if the Save button is selected and confirmed,
            False if the Save button or Confirmation button was not selected
        '''
        if ClinicalAdministerSystem.click_customize_system_settings_save_button():
            ClinicalAdministerSystem.click_confirm_customisation_changes_yes_button()
            return True
        logger.info("Invalid value entered for geometric parameter. Save button not pressed")
        return False
